if (!/^\s*<!DOCTYPE html>/i.test(code)) throw new Error("Start with <!DOCTYPE html>.");
if (!/<html\s+lang=["']en["']\s*>/i.test(code)) throw new Error("<html lang=\"en\"> is required.");
if (!/<head[\s\S]*<meta\s+charset=["']UTF-8["'][\s\S]*<\/head>/i.test(code)) throw new Error("Add <meta charset=\"UTF-8\"> to the head.");
const t = code.match(/<title>([\s\S]*?)<\/title>/i);
if (!t || t[1].trim() !== "About Me") throw new Error("The title must read exactly: About Me");

const h1 = (code.match(/<h1\s*>[\s\S]*?<\/h1\s*>/gi) ?? []).length;
if (h1 !== 1) throw new Error("Exactly one <h1> with your name.");
const ps = code.match(/<p\s*>[\s\S]*?<\/p\s*>/gi) ?? [];
if (ps.length < 2) throw new Error("Write two <p> paragraphs about yourself.");

if (!/<ul[\s\S]*<\/ul>/i.test(code)) throw new Error("Add a <ul> for your wish list.");
const ul = code.match(/<ul[\s\S]*?<\/ul>/i)[0];
const items = (ul.match(/<li[\s\S]*?<\/li>/gi) ?? []).length;
if (items < 3) throw new Error(`The wish list needs at least three <li> items, found ${items}.`);
